"""Summarize node sequence gaps without changing the node."""
import json
import re
import stat
import sys
from collections import Counter
from pathlib import Path


def reject_constant(value):
    raise ValueError("non-finite JSON constant: " + value)


def load_state(folder):
    try:
        raw = (folder / "state.json").read_bytes()
    except FileNotFoundError:
        return None, False
    except OSError:
        return None, True
    try:
        value = json.loads(raw, parse_constant=reject_constant)
    except (ValueError, UnicodeError):
        return None, True
    if not isinstance(value, dict) or not isinstance(value.get("channels"), dict):
        return None, True
    return value["channels"], False


def read_records(paths, bad):
    values = []
    for path in paths:
        parts = path.read_bytes().split(b"\n")
        for line_no, raw in enumerate(parts[:-1], 1):
            try:
                record = json.loads(raw, parse_constant=reject_constant)
            except (ValueError, UnicodeError):
                bad.append({"file": path.name, "line": line_no, "why": "bad_json"})
                continue
            if (not isinstance(record, dict) or type(record.get("seq")) is not int
                    or record["seq"] < 1):
                bad.append({"file": path.name, "line": line_no, "why": "no_seq"})
            else:
                values.append(record["seq"])
        if parts[-1]:
            bad.append({"file": path.name, "line": len(parts), "why": "torn"})
    return values


def channel_paths(files, channel):
    pattern = re.compile(rf"{channel}\.([0-9]{{12}})\.jsonl")
    numbered = []
    active = None
    for path in files:
        match = pattern.fullmatch(path.name)
        if match:
            numbered.append((int(match.group(1)), path))
        elif path.name == channel + ".active.jsonl":
            active = path
    numbered.sort(key=lambda item: item[0])
    paths = [path for _, path in numbered]
    if active is not None:
        paths.append(active)
    return paths


def summarize(folder):
    files = [path for path in folder.iterdir()
             if stat.S_ISREG(path.lstat().st_mode)]
    state, bad_state = load_state(folder)
    bad = []
    channels = {}
    for channel in ("obs", "must"):
        values = read_records(channel_paths(files, channel), bad)
        distinct = sorted(set(values))
        first = distinct[0] if distinct else None
        last = distinct[-1] if distinct else None
        fields = state.get(channel) if state is not None else None
        valid = (isinstance(fields, dict)
                 and type(fields.get("next_seq")) is int
                 and (channel != "must" or type(fields.get("acked_upto")) is int))
        if state is not None and not valid:
            bad_state = True
        next_seq = fields["next_seq"] if valid else None
        channels[channel] = {
            "count": len(values),
            "first": first,
            "last": last,
            "missing": [[left + 1, right - 1]
                        for left, right in zip(distinct, distinct[1:])
                        if right > left + 1],
            "dup": sorted(seq for seq, count in Counter(values).items() if count >= 2),
            "next_seq": next_seq,
            "unacked": (sum(seq > fields["acked_upto"] for seq in distinct)
                        if valid and channel == "must" else None),
            "stale_next": (next_seq != last + 1 if valid and last is not None else None),
        }
    if bad_state:
        bad.append({"file": "state.json", "line": None, "why": "bad_state"})
    bad.sort(key=lambda item: (item["file"],
                               0 if item["line"] is None else item["line"],
                               item["why"]))
    return {"v": 1, "channels": channels, "bad": bad}


def main(argv=None):
    args = sys.argv[1:] if argv is None else argv
    if len(args) != 1:
        return 2
    folder = Path(args[0])
    if not folder.is_dir():
        return 2
    print(json.dumps(summarize(folder), separators=(",", ":")))
    return 0


if __name__ == "__main__":
    sys.exit(main())
